package com.xdownload.mobile;
import android.app.*;import android.content.*;import android.hardware.biometrics.BiometricManager;import android.hardware.biometrics.BiometricPrompt;import android.os.*;import android.net.Uri;import android.provider.OpenableColumns;import android.security.keystore.*;import android.view.WindowManager;import android.widget.*;
import java.io.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.util.*;import java.util.concurrent.*;
/** Device-bound encrypted copies. Strong biometric required for every import/export. No plaintext in app cache. */
public final class BiometricVaultActivity extends SecureActivity {
 static final String ALIAS="xdownload.biometric.v1";static final long MAX=16L*1024*1024;
 final ExecutorService io=Executors.newSingleThreadExecutor();volatile boolean dead=false;boolean busy=false,en;TextView status;LinearLayout rows;Button add;File selected;CancellationSignal signal;
 String tr(String a,String b){return en?b:a;}
 File folder(){return new File(getFilesDir(),"private-vault");}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);en=Store.settings(this).getBoolean("english",false);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(24,24,24,24);TextView title=new TextView(this);title.setText(tr("الخزنة بالبصمة","Biometric vault"));title.setTextSize(24);page.addView(title);status=new TextView(this);status.setText(tr("نسخ مشفرة مرتبطة بهذا الجهاز. حد الملف 16 MiB. الأصل لا يُحذف. فقدان المفتاح أو حذف التطبيق قد يفقد النسخ.","Device-bound encrypted copies, 16 MiB/file. Originals are kept. Removing the app or losing the key may make copies unreadable."));page.addView(status);add=new Button(this);add.setText(tr("إضافة نسخة مشفرة","Add encrypted copy"));add.setOnClickListener(v->{if(!busy)startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),41);});page.addView(add);ScrollView scroll=new ScrollView(this);rows=new LinearLayout(this);rows.setOrientation(1);scroll.addView(rows);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(page);render();}
 void setBusy(boolean b,String msg){busy=b;add.setEnabled(!b);status.setText(msg);render();}
 android.content.SharedPreferences index(){return getSharedPreferences("biometric_vault_index",0);}
 void render(){rows.removeAllViews();File[] files=folder().listFiles((d,n)->n.matches("[a-f0-9-]{36}\\.xdb"));if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified).reversed());for(File f:files){String name=index().getString(f.getName(),"Encrypted file");Button b=new Button(this);b.setAllCaps(false);b.setText(name+" • "+MainActivity.size(f.length()));b.setEnabled(!busy);b.setOnClickListener(v->{selected=f;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,name),42);});rows.addView(b);}}
 String displayName(Uri u){try(android.database.Cursor c=getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return HttpEngine.safeName(c.getString(0));}catch(Exception ignored){}return "file";}
 javax.crypto.SecretKey key(boolean create)throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias(ALIAS)){if(!create)throw new IOException("Vault key is missing");KeyGenerator gen=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");KeyGenParameterSpec.Builder b=new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setKeySize(256).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setUserAuthenticationRequired(true).setInvalidatedByBiometricEnrollment(true);if(Build.VERSION.SDK_INT>=30)b.setUserAuthenticationParameters(0,KeyProperties.AUTH_BIOMETRIC_STRONG);else b.setUserAuthenticationValidityDurationSeconds(-1);gen.init(b.build());gen.generateKey();}return (javax.crypto.SecretKey)ks.getKey(ALIAS,null);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null||busy)return;Uri u=data.getData();if(request==41)authenticate(true,u,null,displayName(u));else if(request==42&&selected!=null)authenticate(false,u,selected,index().getString(selected.getName(),"file"));}
 void authenticate(boolean encrypt,Uri u,File f,String name){try{BiometricManager bm=getSystemService(BiometricManager.class);int available=Build.VERSION.SDK_INT>=30?bm.canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_STRONG):bm.canAuthenticate();if(available!=BiometricManager.BIOMETRIC_SUCCESS)throw new IOException("Enroll a supported strong biometric first");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");if(encrypt)cipher.init(Cipher.ENCRYPT_MODE,key(true));else{try(InputStream in=new FileInputStream(f)){cipher.init(Cipher.DECRYPT_MODE,key(false),new GCMParameterSpec(128,FileTools.readExact(in,12)));}}setBusy(true,tr("تأكيد الهوية","Confirm identity"));signal=new CancellationSignal();new BiometricPrompt.Builder(this).setTitle(tr("فتح الخزنة","Unlock vault")).setNegativeButton(tr("إلغاء","Cancel"),getMainExecutor(),(d,w)->setBusy(false,tr("أُلغي الطلب","Cancelled"))).build().authenticate(new BiometricPrompt.CryptoObject(cipher),signal,getMainExecutor(),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){if(dead)return;Cipher authorized=r.getCryptoObject()==null?null:r.getCryptoObject().getCipher();if(authorized==null){setBusy(false,"Authentication failed");return;}setBusy(true,tr("معالجة الملف…","Processing file…"));io.execute(()->process(encrypt,u,f,name,authorized));}@Override public void onAuthenticationError(int code,CharSequence message){if(!dead)setBusy(false,message.toString());}});}catch(Exception e){setBusy(false,String.valueOf(e.getMessage()));}}
 void process(boolean encrypt,Uri u,File f,String name,Cipher cipher){byte[] plain=null;File tmp=null;try{cipher.updateAAD("XDB1".getBytes(java.nio.charset.StandardCharsets.US_ASCII));if(encrypt){if(!folder().isDirectory()&&!folder().mkdirs())throw new IOException("Cannot create vault");plain=read(getContentResolver().openInputStream(u),MAX);byte[] encrypted=cipher.doFinal(plain);if(dead)throw new IOException("Cancelled");tmp=File.createTempFile("pending-",".tmp",folder());try(FileOutputStream out=new FileOutputStream(tmp)){out.write(cipher.getIV());out.write(encrypted);out.getFD().sync();}File dest=new File(folder(),UUID.randomUUID()+".xdb");if(!tmp.renameTo(dest))throw new IOException("Cannot publish encrypted copy");tmp=null;index().edit().putString(dest.getName(),name).commit();report(tr("تم حفظ نسخة مشفرة؛ الأصل كما هو","Encrypted copy saved; original retained"));}else{try(InputStream in=new FileInputStream(f)){FileTools.readExact(in,12);byte[] encrypted=read(in,MAX+16);plain=cipher.doFinal(encrypted);}if(dead)throw new IOException("Cancelled");try(OutputStream out=getContentResolver().openOutputStream(u,"w")){if(out==null)throw new IOException("Cannot write file");out.write(plain);}report(tr("تم تصدير الملف بعد التحقق من التشفير","Authenticated file exported"));}}catch(Exception e){report(tr("فشل: ","Failed: ")+e.getMessage());}finally{if(plain!=null)Arrays.fill(plain,(byte)0);if(tmp!=null)tmp.delete();}}
 static byte[] read(InputStream stream,long max)throws IOException{if(stream==null)throw new IOException("Cannot open file");try(InputStream in=stream;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted()||(long)out.size()+n>max)throw new IOException("File exceeds vault limit or operation cancelled");out.write(b,0,n);}return out.toByteArray();}}
 void report(String s){runOnUiThread(()->{if(!dead)setBusy(false,s);});}
 @Override protected void onDestroy(){dead=true;if(signal!=null)signal.cancel();io.shutdownNow();super.onDestroy();}
}